import { useCallback, useRef, useEffect } from 'react';

// A short two-note chime (synthesized, not a recording), embedded as base64 so no separate audio asset is needed
const NOTIFICATION_SOUND = 'data:audio/wav;base64,';

export function useNotificationAlerts() {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const permissionGranted = useRef(false);

  // Initialize audio element
  useEffect(() => {
    audioRef.current = new Audio(NOTIFICATION_SOUND);
    audioRef.current.volume = 0.5;
    
    // Check/request notification permission
    if ('Notification' in window) {
      if (Notification.permission === 'granted') {
        permissionGranted.current = true;
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission().then(permission => {
          permissionGranted.current = permission === 'granted';
        });
      }
    }
  }, []);

  const playSound = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(() => {
        // Audio play failed - user hasn't interacted with page yet
      });
    }
  }, []);

  const showBrowserNotification = useCallback((title: string, body: string, onClick?: () => void) => {
    // Don't show if page is visible
    if (document.visibilityState === 'visible') {
      playSound();
      return;
    }

    if ('Notification' in window && Notification.permission === 'granted') {
      const notification = new Notification(title, {
        body,
        icon: '/favicon.png',
        badge: '/favicon.png',
        tag: 'pfs-notification', // Prevents duplicate notifications
      });

      notification.onclick = () => {
        window.focus();
        notification.close();
        onClick?.();
      };

      playSound();
    } else {
      playSound();
    }
  }, [playSound]);

  const requestPermission = useCallback(async () => {
    if ('Notification' in window && Notification.permission !== 'granted') {
      const permission = await Notification.requestPermission();
      permissionGranted.current = permission === 'granted';
      return permission === 'granted';
    }
    return Notification.permission === 'granted';
  }, []);

  return {
    playSound,
    showBrowserNotification,
    requestPermission,
    isSupported: 'Notification' in window,
  };
}
